/**
 * @file Slice of the state object that handles the tabular datasets loaded
 * by the user.
 */
import { createSlice } from '@reduxjs/toolkit';
import { deleteItemsByIds, EMPTY_COLLECTION, } from '~/utils/collections';
const initialState = EMPTY_COLLECTION;
const { actions, reducer } = createSlice({
    name: 'datasets',
    initialState,
    reducers: {
        removeDatasets(state, action) {
            deleteItemsByIds(state, action.payload);
        },
    },
});
export const { removeDatasets } = actions;
export default reducer;
