import { createSlice } from '@reduxjs/toolkit';
import { nanoid } from 'nanoid';
const initialState = {
    target: [],
    status1: [],
    status2: [],
    armed: false,
    DET: false,
    health: false,
    charging: false,
};
const { actions, reducer } = createSlice({
    name: 'targetCNF',
    initialState,
    reducers: {
        addtargetCNF(state, action) {
            const tar = { ...action.payload, id: nanoid(10) };
            state.target.push(tar);
        },
        removetargetCNF(state, action) {
            state.target = state.target.filter((target) => target.id !== action.payload);
        },
        updateStatus1Sdal(state, action) {
            state.status1 = action.payload;
        },
        updateStatus2Sdal(state, action) {
            state.status2 = action.payload;
        },
        updateArmedStatus(state, action) {
            state.armed = action.payload;
        },
        updateDETStatus(state, action) {
            state.DET = action.payload;
        },
        updateHealth(state, action) {
            state.health = action.payload;
        },
        updateChargingStatus(state, action) {
            state.charging = action.payload;
        },
    },
});
export const { addtargetCNF, removetargetCNF, updateStatus1Sdal, updateStatus2Sdal, updateArmedStatus, updateDETStatus, updateHealth, updateChargingStatus, } = actions;
export default reducer;
