/**
 * @file Slice of the state object that handles the state of the UAV details
 * dialog.
 */
import { createSlice } from '@reduxjs/toolkit';
import { setSelection } from '~/features/map/selection';
import { globalIdToUavId, isUavId } from '~/model/identifiers';
import { noPayload } from '~/utils/redux';
import { UAV_DETAILS_DIALOG_MIN_WIDTH } from './constants';
import { UAVDetailsDialogTab } from './types';
const initialState = {
    open: false,
    selectedUAVId: undefined,
    selectedTab: UAVDetailsDialogTab.PREFLIGHT,
    position: { x: 0, y: 0 },
    width: UAV_DETAILS_DIALOG_MIN_WIDTH,
    LoadMission: false,
    color: '',
    missionPoints: []
};
const { actions, reducer } = createSlice({
    name: 'uav-details',
    initialState,
    reducers: {
        openUAVDetailsDialog(state, { payload }) {
            state.selectedUAVId = payload;
            state.open = true;
        },
        closeUAVDetailsDialog: noPayload((state) => {
            state.open = false;
        }),
        DownloadMissionTrue: noPayload((state) => {
            state.LoadMission = !state.LoadMission;
        }),
        DownloadMissionFalse: noPayload((state) => {
            state.LoadMission = false;
        }),
        setColorCode(state, { payload }) {
            state.color = payload;
        },
        setMissionFromServer(state, { payload }) {
            state.missionPoints = payload;
        },
        setSelectedTabInUAVDetailsDialog(state, { payload }) {
            state.selectedTab = payload;
        },
        setSelectedUAVIdInUAVDetailsDialog(state, { payload }) {
            state.selectedUAVId = payload;
        },
        setUAVDetailsDialogPosition(state, { payload }) {
            state.position = payload;
        },
        setUAVDetailsDialogWidth(state, { payload }) {
            state.width = payload;
        },
    },
    extraReducers(builder) {
        builder.addCase(setSelection, (state, { payload: selection }) => {
            const selectedUAV = selection.find(isUavId);
            if (selectedUAV) {
                state.selectedUAVId = globalIdToUavId(selectedUAV);
            }
        });
    },
});
export const { openUAVDetailsDialog, closeUAVDetailsDialog, setSelectedTabInUAVDetailsDialog, setSelectedUAVIdInUAVDetailsDialog, setUAVDetailsDialogPosition, setUAVDetailsDialogWidth, DownloadMissionTrue, DownloadMissionFalse, setColorCode, setMissionFromServer, } = actions;
export const getColorCode = (state) => state.dialogs.uavDetails.color;
export const getMissionFromServer = (state) => state.dialogs.uavDetails.missionPoints;
export const isUAVDetailsDialogOpen = (state) => state.dialogs.uavDetails.open;
export const getSelectedUAVIdInUAVDetailsDialog = (state) => state.dialogs.uavDetails.selectedUAVId;
export const getSelectedTabInUAVDetailsDialog = (state) => state.dialogs.uavDetails.selectedTab;
export const getUAVDetailsDialogPosition = (state) => state.dialogs.uavDetails.position;
export const getUAVDetailsDialogWidth = (state) => state.dialogs.uavDetails.width;
export const getLoadMissionState = (state) => state.dialogs.uavDetails.LoadMission;
export default reducer;
