import { createSlice } from '@reduxjs/toolkit';
import { noPayload } from '~/utils/redux';
const initialState = {
    coverage: 500,
    gridSpacing: 50,
    Direction: 'ClockWise Direction',
    skip_waypoint: 0,
    radius: 0,
    speed: 18,
    groupsplitDialog: false,
    numOfGroups: 0,
    group: {},
    selectedTab: 'Create',
    time: 0,
    timerRunning: false,
    missionByUav: {},
    // Matches medur_fixed_wing.py's hardcoded different_height default
    // (base 300, spaced 10 apart) so the UI starts at the same values the
    // swarm computer already assumes before any "different" command is sent.
    baseAltitude: 300,
    altitudeStep: 10,
    simPattern: 'Line',
    simVehicle: 'plane',
    NoOfUAVs: 1,
    UAVSpacing: 10,
    UAVRow: NaN,
    UAVColumn: NaN,
};
const { actions, reducer } = createSlice({
    name: 'socketswarm',
    initialState,
    reducers: {
        changeCoverage(state, action) {
            state.coverage = action.payload.coverage;
        },
        changeGridSpacing(state, action) {
            state.gridSpacing = action.payload.gridSpacing;
        },
        changeDirection(state, action) {
            state.Direction = action.payload.direction;
        },
        changeWayPoint(state, action) {
            state.skip_waypoint = action.payload.waypoint;
        },
        changeRadius(state, action) {
            state.radius = action.payload.radius;
        },
        changeSpeed(state, action) {
            state.speed = action.payload.speed;
        },
        changeBaseAltitude(state, action) {
            state.baseAltitude = action.payload.baseAltitude;
        },
        changeAltitudeStep(state, action) {
            state.altitudeStep = action.payload.altitudeStep;
        },
        openGroupSplitDialog: noPayload((state) => {
            state.groupsplitDialog = true;
        }),
        closeGroupSplitingDialog: noPayload((state) => {
            state.groupsplitDialog = false;
        }),
        addGroup: (state, action) => {
            state.group[action.payload.id] = action.payload.uavs;
        },
        changeSelectedTab: (state, action) => {
            state.selectedTab = action.payload;
        },
        resetGroup: noPayload((state) => {
            state.group = {};
        }),
        deleteGroup: (state, action) => {
            delete state.group[action.payload];
        },
        setTime: (state, actions) => {
            state.time = actions.payload;
        },
        setTimerRunning: (state, action) => {
            state.timerRunning = action.payload;
        },
        // Merges (not replaces) so a search response for UAV2 and a split
        // response for UAV1+UAV3 both stay on the map at once -- each only
        // overwrites the specific UAV ids present in its own payload, so a
        // UAV keeps showing its last route until it's actually given a new
        // command of its own.
        mergeMissionForUavs(state, action) {
            state.missionByUav = { ...state.missionByUav, ...action.payload };
        },
        clearMissionByUav: noPayload((state) => {
            state.missionByUav = {};
        }),
        changeNoUAVs(state, action) {
            state.NoOfUAVs = action.payload.NoOfUAVs;
        },
        changeUavSpacing(state, action) {
            state.UAVSpacing = action.payload.UAVSpacing;
        },
        changeUavRow(state, action) {
            state.UAVRow = action.payload.UAVRow;
        },
        changeUavColumn(state, action) {
            state.UAVColumn = action.payload.UAVColumn;
        },
        changeSimPattern(state, action) {
            state.simPattern = action.payload.simPattern;
        },
        changeSimVehicle(state, action) {
            state.simVehicle = action.payload.simVehicle;
        },
    },
});
export const { changeWayPoint, changeDirection, changeCoverage, changeGridSpacing, changeRadius, changeSpeed, changeBaseAltitude, changeAltitudeStep, openGroupSplitDialog, closeGroupSplitingDialog, addGroup, changeSelectedTab, resetGroup, setTime, setTimerRunning, mergeMissionForUavs, clearMissionByUav, changeNoUAVs, changeUavSpacing, changeUavRow, changeUavColumn, changeSimPattern, changeSimVehicle, } = actions;
export default reducer;
